// Generated by afz-rust: the JSON readers every generated construction block uses.
//
// The readers are strict about shape and say so in the error, because the message reaches the
// scan report through the `unmaterializable` rejection detail.
use serde_json::Map;
use serde_json::Value;

pub type R<T> = ::std::result::Result<T, String>;

fn show(value: &Value) -> String {
    let text = value.to_string();
    if text.len() > 120 {
        format!("{}…", &text[..text.floor_char_boundary(120)])
    } else {
        text
    }
}

pub fn b_of(value: &Value) -> R<bool> {
    value.as_bool().ok_or_else(|| format!("{} is not a boolean", show(value)))
}

/// Integers arrive as JSON numbers or, for a `BigInt` node, as a decimal string.
pub fn i_of(value: &Value) -> R<i64> {
    if let Some(number) = value.as_i64() {
        return Ok(number);
    }
    if let Some(text) = value.as_str() {
        if let Ok(number) = text.parse::<i64>() {
            return Ok(number);
        }
    }
    if let Some(number) = value.as_f64() {
        if number.fract() == 0.0 {
            return Ok(number as i64);
        }
    }
    Err(format!("{} is not an integer", show(value)))
}

pub fn u_of(value: &Value) -> R<u64> {
    if let Some(number) = value.as_u64() {
        return Ok(number);
    }
    if let Some(text) = value.as_str() {
        if let Ok(number) = text.parse::<u64>() {
            return Ok(number);
        }
    }
    if let Some(number) = value.as_f64() {
        if number.fract() == 0.0 && number >= 0.0 {
            return Ok(number as u64);
        }
    }
    Err(format!("{} is not a non-negative integer", show(value)))
}

/// JSON has no token for the non-finite values; the wire carries them by name.
pub fn f_of(value: &Value) -> R<f64> {
    if let Some(number) = value.as_f64() {
        return Ok(number);
    }
    if let Some(text) = value.as_str() {
        return match text {
            "nan" | "NaN" => Ok(f64::NAN),
            "infinity" | "Infinity" => Ok(f64::INFINITY),
            "-infinity" | "negativeInfinity" | "-Infinity" => Ok(f64::NEG_INFINITY),
            other => other.parse::<f64>().map_err(|_| format!("{other} is not a number")),
        };
    }
    Err(format!("{} is not a number", show(value)))
}

pub fn c_of(value: &Value) -> R<char> {
    let text = value.as_str().ok_or_else(|| format!("{} is not a string", show(value)))?;
    let mut chars = text.chars();
    match (chars.next(), chars.next()) {
        (Some(c), None) => Ok(c),
        _ => Err(format!("{text:?} is not exactly one character")),
    }
}

pub fn s_of(value: &Value) -> R<String> {
    value.as_str().map(|s| s.to_string()).ok_or_else(|| format!("{} is not a string", show(value)))
}

pub fn arr_of(value: &Value) -> R<Vec<Value>> {
    value.as_array().cloned().ok_or_else(|| format!("{} is not an array", show(value)))
}

pub fn obj_of(value: &Value) -> R<Map<String, Value>> {
    value.as_object().cloned().ok_or_else(|| format!("{} is not an object", show(value)))
}

pub fn entries_of(value: &Value) -> R<Vec<(String, Value)>> {
    Ok(obj_of(value)?.into_iter().collect())
}

pub fn field<'a>(object: &'a Map<String, Value>, name: &str) -> R<&'a Value> {
    object.get(name).ok_or_else(|| format!("the object has no field {name}"))
}
